import { apiFetch,getAtlasClient } from "/modules/atlas-client.js";
const $=selector=>document.querySelector(selector);const client=await getAtlasClient();const {data}=await client.auth.getSession();if(!data.session)location.replace("/#passes");
let currentTicket=null;
function formatRemaining(seconds){const total=Math.max(0,Math.floor(seconds)),hours=Math.floor(total/3600),minutes=Math.floor(total%3600/60),secs=total%60;return{compact:`${String(hours).padStart(2,"0")}:${String(minutes).padStart(2,"0")}:${String(secs).padStart(2,"0")}`,long:`Faltam ${hours} horas, ${minutes} minutos e ${secs} segundos.`}}
function updateFreeCountdown(){if(!currentTicket?.free||!currentTicket.waitEndsAt)return;const seconds=Math.max(0,Math.ceil((new Date(currentTicket.waitEndsAt).getTime()-Date.now())/1000)),remaining=formatRemaining(seconds),ready=seconds<=0;$("#queuePosition").textContent=remaining.compact;$("#queueTitle").textContent=ready?"É a sua vez de jogar.":remaining.long;$("#estimatedWait").textContent=ready?"Agora":remaining.compact;$("#ticketStatus").textContent=ready?"Pronto":"Fila grátis";$("#queueProgress").style.width=`${Math.max(2,Math.min(100,(1-seconds/(11*86400))*100))}%`;$("#statusKicker").textContent=ready?"SUA SESSÃO ESTÁ PRONTA":"FILA GRÁTIS · CONTAGEM REGRESSIVA";$("#queueMessage").textContent=ready?"O servidor está reservando sua sessão nesta tela.":"Seu prazo individual está salvo no servidor e continua correndo mesmo com a página fechada."}
function render(ticket){currentTicket=ticket;if(!ticket){$("#queuePosition").textContent="—";$("#queueTitle").textContent="Você ainda não está na fila.";$("#queueMessage").textContent="Escolha uma fila para receber sua posição.";$("#buyPass").classList.remove("hidden");return}$("#vipUpsell").classList.toggle("hidden",!ticket.free);$("#positionDisplay").classList.toggle("countdown-mode",Boolean(ticket.free));$("#positionPrefix").classList.toggle("hidden",Boolean(ticket.free));if(ticket.free){$("#sessionDuration").textContent="15 min grátis";updateFreeCountdown();return}const position=Math.max(1,Number(ticket.position||1)),total=Number(ticket.total||967),ready=position<=1||ticket.status==="ready";$("#queuePosition").textContent=position;$("#sessionDuration").textContent=`${ticket.durationMinutes} min`;$("#estimatedWait").textContent=ready?"Agora":`~${ticket.estimatedMinutes} min`;$("#ticketStatus").textContent=ready?"Pronto":ticket.priority?"Prioridade ativa":"Na fila";$("#queueProgress").style.width=`${Math.max(2,Math.min(100,(1-position/total)*100))}%`;$("#statusKicker").textContent=ready?"SUA SESSÃO ESTÁ PRONTA":ticket.priority?"FILA PRIORITÁRIA · SUA POSIÇÃO":"SUA POSIÇÃO NA FILA";$("#queueTitle").textContent=ready?"É a sua vez de jogar.":`Você está na posição #${position}.`;$("#queueMessage").textContent=ready?"O servidor está reservando sua sessão nesta tela.":ticket.priority?"Sua sessão completa avança com prioridade. A página atualiza automaticamente.":"Sua posição avança automaticamente até a sessão ser liberada."}
async function refresh(){try{const queue=await apiFetch("/api/cloud-queue");render(queue.myTicket)}catch(error){$("#queueMessage").textContent=error.message}}
async function initializeQueue(){const navigation=performance.getEntriesByType("navigation")[0];if(navigation?.type==="reload"){try{const result=await apiFetch("/api/free-queue",{method:"POST",body:JSON.stringify({reset:true})});render(result.queue?.myTicket);return}catch(error){$("#queueMessage").textContent=error.message}}await refresh()}
initializeQueue();setInterval(refresh,12000);$("#homeButton").addEventListener("click",()=>location.replace("/"));
setInterval(updateFreeCountdown,1000);
